import { Component } from '@angular/core';

@Component({
  selector: 'app-about',
  templateUrl: './about.component.html',
  styleUrls: ['./about.component.css']
})
export class AboutComponent {

}
<section class="container mt-5 about-section fade-in" id="about">
  <h2 class="section-title">About Me</h2>
  <p class="lead mt-3">
    I’m a self-motivated and highly passionate Full Stack Developer, eager to contribute to team success through hard work, attention to detail, and a never-give-up attitude. I have hands-on experience with technologies like Angular, ReactJS, Java, Spring Boot, and MySQL. I enjoy solving problems and building useful, efficient applications that create impact.
  </p>
</section>
